fn into_iter(self) -> I {
    self
}

fn next(&mut self) -> Option<A> {
    self.spec_next()
}

fn spec_next(&mut self) -> Option<T> {
    if self.start < self.end {
        let old = self.start;
        // SAFETY: just checked precondition
        self.start = unsafe { Step::forward_unchecked(old, 1) };
        Some(old)
    } else {
        None
    }
}

unsafe fn forward_unchecked(start: Self, n: usize) -> Self {
    // SAFETY: the caller has to guarantee that `start + n` doesn't overflow.
    unsafe { start.unchecked_add(n as Self) }
}

pub const unsafe fn unchecked_add(self, rhs: Self) -> Self {
    assert_unsafe_precondition!(
        check_language_ub,
        concat!(stringify!($SelfT), "::unchecked_add cannot overflow"),
        (
            lhs: $SelfT = self,
            rhs: $SelfT = rhs,
        ) => !lhs.overflowing_add(rhs).1,
    );

    // SAFETY: this is guaranteed to be safe by the caller.
    unsafe {
        intrinsics::unchecked_add(self, rhs)
    }
}

pub(crate) const fn check_language_ub() -> bool {
    // Only used for UB checks so we may const_eval_select.
    const_eval_select!(
        @capture { } -> bool:
        if const {
            // Always disable UB checks.
            false
        } else {
            // Disable UB checks in Miri.
            !cfg!(miri)
        }
    ) && intrinsics::ub_checks()
}

const fn precondition_check($($name:$ty),*) {
    if !$e {
        let msg = concat!("unsafe precondition(s) violated: ", $message,
            "\n\nThis indicates a bug in the program. \
            This Undefined Behavior check is optional, and cannot be relied on for safety.");
        ::core::panicking::panic_nounwind_fmt(::core::fmt::Arguments::from_str(msg), false);
    }
}

#[rustc_nounwind]
#[rustc_intrinsic]
pub const fn add_with_overflow<T: Copy>(x: T, y: T) -> (T, bool);

#[rustc_nounwind]
#[rustc_intrinsic]
pub const unsafe fn unchecked_add<T: Copy>(x: T, y: T) -> T;

pub const fn ub_checks() -> bool {
    cfg!(ub_checks)
}

pub const fn unlikely(b: bool) -> bool {
    if b {
        cold_path();
        true
    } else {
        false
    }
}

pub const fn len(&self) -> usize {
    ptr::metadata(self)
}

pub const fn metadata<T: PointeeSized>(ptr: *const T) -> <T as Pointee>::Metadata {
    ptr_metadata(ptr)
}

pub const fn checked_add(self, rhs: Self) -> Option<Self> {
    // This used to use `overflowing_add`, but that means it ends up being
    // a `wrapping_add`, losing some optimization opportunities. Notably,
    // phrasing it this way helps `.checked_add(1)` optimize to a check
    // against `MAX` and a `add nuw`.
    // Per <https://github.com/rust-lang/rust/pull/124114#issuecomment-2066173305>,
    // LLVM is happy to re-form the intrinsic later if useful.

    if intrinsics::unlikely(intrinsics::add_with_overflow(self, rhs).1) {
        None
    } else {
        // SAFETY: Just checked it doesn't overflow
        Some(unsafe { intrinsics::unchecked_add(self, rhs) })
    }
}

pub const fn ok_or<E: [const] Destruct>(self, err: E) -> Result<T, E> {
    match self {
        Some(v) => Ok(v),
        None => Err(err),
    }
}

fn branch(self) -> ControlFlow<Self::Residual, Self::Output> {
    match self {
        Ok(v) => ControlFlow::Continue(v),
        Err(e) => ControlFlow::Break(Err(e)),
    }
}

fn from_residual(residual: Result<convert::Infallible, E>) -> Self {
    match residual {
        Err(e) => Err(From::from(e)),
    }
}

fn from(t: T) -> T {
    t
}

pub fn as_os_str(&self) -> &OsStr {
    &self.inner
}

fn as_bytes(&self) -> &[u8] {
    &self.as_inner().inner
}

fn as_inner(&self) -> &Slice {
    &self.inner
}

pub const fn is_empty(&self) -> bool {
    self.len() == 0
}

pub const fn and_then<U, F>(self, f: F) -> Option<U>
where
    F: [const] FnOnce(T) -> Option<U> + [const] Destruct,
{
    match self {
        Some(x) => f(x),
        None => None,
    }
}

fn ne(&self, other: &[U; N]) -> bool {
    SpecArrayEq::spec_ne(self, other)
}

fn spec_ne(a: &[T; N], b: &[U; N]) -> bool {
    !Self::spec_eq(a, b)
}

fn spec_eq(a: &[T; N], b: &[U; N]) -> bool {
    // SAFETY: Arrays are compared element-wise, and don't add any padding
    // between elements, so when the elements are `BytewiseEq`, we can
    // compare the entire array at once.
    unsafe { crate::intrinsics::raw_eq(a, crate::mem::transmute(b)) }
}

fn ne(&self, other: &&B) -> bool {
    PartialEq::ne(*self, *other)
}

fn ne(&self, other: &Rhs) -> bool {
    !self.eq(other)
}

fn eq(&self, other: &[U]) -> bool {
    let len = self.len();
    if len == other.len() {
        // SAFETY: Just checked that they're the same length, and the pointers
        // come from references-to-slices so they're guaranteed readable.
        unsafe { SlicePartialEq::equal_same_length(self.as_ptr(), other.as_ptr(), len) }
    } else {
        false
    }
}

pub const fn as_ptr(&self) -> *const T {
    self as *const [T] as *const T
}

unsafe fn equal_same_length(lhs: *const Self, rhs: *const B, len: usize) -> bool {
    // SAFETY: by our precondition, `lhs` and `rhs` are guaranteed to be valid
    // for reading `len` values, which also means the size is guaranteed
    // not to overflow because it exists in memory;
    unsafe {
        let size = crate::intrinsics::unchecked_mul(len, Self::SIZE);
        compare_bytes(lhs as _, rhs as _, size) == 0
    }
}

pub fn contains(&self, x: &T) -> bool
where
    T: PartialEq,
{
    cmp::SliceContains::slice_contains(x, self)
}

default fn slice_contains(&self, x: &[Self]) -> bool {
    if size_of::<T>() == 1 {
        // SAFETY: `BytewiseEq` guarantees that values have no padding or provenance and
        // compare like their underlying bytes. Since `T` is one byte, both the value and
        // slice can be read as `u8`s.
        let (byte, bytes) = unsafe {
            (transmute_copy::<T, u8>(self), from_raw_parts(x.as_ptr().cast::<u8>(), x.len()))
        };
        memchr::memchr(byte, bytes).is_some()
    } else {
        x.iter().any(|y| *y == *self)
    }
}

pub const fn memchr(x: u8, text: &[u8]) -> Option<usize> {
    // Fast path for small slices.
    let result =
        if text.len() < 2 * USIZE_BYTES { memchr_naive(x, text) } else { memchr_aligned(x, text) };
    if let Some(index) = result {
        // SAFETY: Both implementations only return an index from within `text`.
        unsafe { crate::hint::assert_unchecked(index < text.len()) };
    }
    result
}

const fn memchr_naive(x: u8, text: &[u8]) -> Option<usize> {
    let mut i = 0;

    // FIXME(const-hack): Replace with `text.iter().pos(|c| *c == x)`.
    while i < text.len() {
        if text[i] == x {
            return Some(i);
        }

        i += 1;
    }

    None
}
